export class LeadRepository {
  async getAll() {
    return prisma.lead.findMany({ orderBy: { createdAt: "desc" } });
  }
}

async createLead(data: CreateLeadInput) {
  if (!data.phone.trim()) throw new Error("Phone required");
  return this.repo.create({ ...data, phone: data.phone.replace(/\D/g, "") });
}

async createLead(req: Request) {
  try {
    const lead = await this.service.createLead(await req.json());
    return NextResponse.json({ success: true, data: lead }, { status: 201 });
  } catch (e) {
    return NextResponse.json({ success: false, error: String(e) }, { status: 400 });
  }
}
